    "description": "汇丰策略师表示，受韩国今年创纪录的经常账户盈余推动，始于2021年的美元/韩元上涨趋势已经结束。亚洲外汇研究主管Joey Chew在9月7日的一份报告中表示，该银行将美元/韩元2026年底和2027年中的预测从1500分别下调至1320和1280。根据1月至7月的数据，经常账户盈余按年化计算达到4000亿美元，这对该汇率而言是一个“颠覆性”的因素。这一数字超过了2021年至2025年累计的3600亿美元盈余。（新浪财经）",
