    "author": "澎湃新闻记者 杨宝宝",
    "description": "2026年全国科普月之际，9月6日下午，“《飞天逐梦向火星》图书分享会”在杨浦区图书馆“静思讲坛”举行，这也是上海科技教育出版社“哲人石读书会”本年度的第六场活动。 该书的两位作者，天文学家卞毓麟和科普作家施韡以“火星，人类的下一个家园？”为主题，与现场听众分享了人类探索火星的传奇历程、火星探测的最新科学发现，以及未来改造火星和太空移民的愿景。 在分享会上，卞毓麟首先回顾了自己近四十年的火星科普创作之路，本次新书《飞天逐梦向火星》是他呈…",
    "content": "2026年全国科普月之际，9月6日下午，“《飞天逐梦向火星》图书分享会”在杨浦区图书馆“静思讲坛”举行，这也是上海科技教育出版社“哲人石读书会”本年度的第六场活动。 该书的两位作者，天文学家卞毓麟和科普作家施韡以“火星，人类的下一个家园？”为主题，与现场听众分享了人类探索火星的传奇历程、火星探测的最新科学发现，以及未来改造火星和太空移民的愿景。 在分享会上，卞毓麟首先回顾了自己近四十年的火星科普创作之路，本次新书《飞天逐梦向火星》是他呈现人类探火全景的集大成之作。他将人类探索火星的进程凝练为“驯化火星十步走”：从肉…"
