    "description": "当前，国家水网建设正全面提速。今年上半年，包括三峡水运新通道在内的25项重大水利工程开工，接近去年全年开工数量。“十五五”时期水网建设总投资预计突破6万亿元。循着“纲—目—结”三层布局，国家水网建设的骨架、脉络和节点渐次展开。“纲”承担跨流域、跨区域输水的骨干功能，“目”在于把区域性水系进一步连通至地方和终端，“结”承担着水系的调蓄和运行控制功能。（证券时报）",
