    "link": "https://36kr.com/newsflashes/3974004662022662?f=rss",
    "pub_date": "2026-09-08 08:22:31",
    "author": "",
    "description": "当地时间9月7日，环球音乐集团宣布已完成总额2.5亿欧元的股票回购计划。8月31日至9月4日期间，公司回购29.43万股，平均回购价格为每股14.65欧元，交易总额约431.1万欧元。截至9月4日，UMG在该计划下累计回购1655.20万股，合计支付2.5亿欧元。公司表示，该股票回购计划现已完成。（界面）",
    "content": "当地时间9月7日，环球音乐集团宣布已完成总额2.5亿欧元的股票回购计划。8月31日至9月4日期间，公司回购29.43万股，平均回购价格为每股14.65欧元，交易总额约431.1万欧元。截至9月4日，UMG在该计划下累计回购1655.20万股，合计支付2.5亿欧元。公司表示，该股票回购计划现已完成。（界面）"
