    "author": "方子逸/中国科学报",
    "description": "金星没有卫星。但预印本平台arXiv近日公布的一项模拟研究显示，它在近20亿年的时间里可能拥有过一颗卫星，直到最后将其吞噬。厘清这一过程，有助于了解金星过去的宜居性。 金星可能曾拥有一颗卫星。图片来源：NASA images/Shutterstock 在太阳系早期，许多大型天体可能撞击过金星并形成了一颗卫星，其过程可能与月球的形成类似。 “金星极有可能经历过一次能形成卫星的撞击事件。”美国加州大学河滨分校的Stephen Kane说。因…",
    "content": "金星没有卫星。但预印本平台arXiv近日公布的一项模拟研究显示，它在近20亿年的时间里可能拥有过一颗卫星，直到最后将其吞噬。厘清这一过程，有助于了解金星过去的宜居性。 金星可能曾拥有一颗卫星。图片来源：NASA images/Shutterstock 在太阳系早期，许多大型天体可能撞击过金星并形成了一颗卫星，其过程可能与月球的形成类似。 “金星极有可能经历过一次能形成卫星的撞击事件。”美国加州大学河滨分校的Stephen Kane说。因此，金星如今没有卫星就显得很不寻常。于是，Kane和同事模拟了金星如果真的拥有卫…"
