    "description": "“我捐了好几年的钱，一个电话都没给我打过，我才停了一个月，这电话一下子就打过来了。”近日，网友刘女士发视频称，坚持数年月度公益捐赠从未间断，停捐一个月便收到慈善机构催捐电话。相关视频引发关注。 据刘女士自述，她因自己经营的甜品店生意下滑，个人经济压力增大，慎重考虑后决定停止坚持多年的月捐。随后，她接到某基金会工作人员的电话，对方询问：“发现您持续捐款这么多年，是什么原因上个月不捐了呢？”当她解释自己的现实困境，说出“我没钱了”之后，却听…",
    "content": "“我捐了好几年的钱，一个电话都没给我打过，我才停了一个月，这电话一下子就打过来了。”近日，网友刘女士发视频称，坚持数年月度公益捐赠从未间断，停捐一个月便收到慈善机构催捐电话。相关视频引发关注。 据刘女士自述，她因自己经营的甜品店生意下滑，个人经济压力增大，慎重考虑后决定停止坚持多年的月捐。随后，她接到某基金会工作人员的电话，对方询问：“发现您持续捐款这么多年，是什么原因上个月不捐了呢？”当她解释自己的现实困境，说出“我没钱了”之后，却听到电话那头传来一声笑。“我不知道那声笑是什么意思，也许是我多想了。但那一刻，我真…"
