    "description": "对冲基金创始人Chris Rokos据悉将离开英国，成为该国又一位选择离开的高额纳税人和金融界知名人士。一位知情人士称，这位Rokos Capital Management创始人正将居住地转至希腊。此举对希腊而言是一项重大利好，相比之下，对英国构成打击。希腊此前推出相关规则，允许部分外国人就其全部海外收入每年缴纳10万欧元（约11.624万美元）的固定税额。（新浪财经）",
