    "title": "公募9月首周调研逾1400次，科技赛道关注度提升",
    "link": "https://36kr.com/newsflashes/3974000112513286?f=rss",
    "pub_date": "2026-09-08 08:17:54",
    "author": "",
    "description": "进入9月，尽管市场波动加大、行业轮动节奏加快，但公募基金依旧关注科技赛道投资机会。公募排排网数据显示，9月首周（2026年8月31日至9月6日）公募基金合计调研次数达1428次。分行业看，公募机构对电子行业的调研热情最高，上周合计调研次数达303次，无论是被调研公司数量还是被调研次数，均明显领先于其他行业。此外，医药生物、汽车和电力设备等行业也较受关注，分别被调研183次、125次和123次。（上证报）",
