    "description": "新华社奥斯陆9月7日电（记者张玉亮）哥本哈根消息：欧盟委员会主席冯德莱恩7日访问丹麦自治领地格陵兰岛首府努克时宣布，欧盟将推出总额2亿欧元的投资计划，以加强与格陵兰岛的合作。 欧盟委员会当天发布新闻公报说，这项投资计划将在2026年和2027年支持格陵兰岛的相关投资。双方将深化在教育、渔业等领域的合作，改善格陵兰岛的卫星和光缆连接，支持水力发电及关键原材料领域发展。该计划还将支持改善格陵兰岛的住房条件、发展可持续旅游和扶持小企业等。 访…",
    "content": "新华社奥斯陆9月7日电（记者张玉亮）哥本哈根消息：欧盟委员会主席冯德莱恩7日访问丹麦自治领地格陵兰岛首府努克时宣布，欧盟将推出总额2亿欧元的投资计划，以加强与格陵兰岛的合作。 欧盟委员会当天发布新闻公报说，这项投资计划将在2026年和2027年支持格陵兰岛的相关投资。双方将深化在教育、渔业等领域的合作，改善格陵兰岛的卫星和光缆连接，支持水力发电及关键原材料领域发展。该计划还将支持改善格陵兰岛的住房条件、发展可持续旅游和扶持小企业等。 访问期间，冯德莱恩与格陵兰岛自治政府总理延斯-弗雷德里克·尼尔森、丹麦首相弗雷泽里…"
