    "description": "新华社巴拿马城9月7日电（记者李佳旭 许咏政）巴拿马运河管理局新任局长伊利娅·埃斯皮诺7日表示，若未来数月运河流域降雨量仍低于预期，运河每日通航量或于明年年初从32艘进一步降至约29艘。 埃斯皮诺当天正式就任巴拿马运河管理局局长，任期至2033年，系首位执掌该机构的女性。她在就职典礼上说，近年来，巴拿马运河流域经历严重水资源危机，运河通航和数百万居民用水安全均受到威胁。为此，运河管理局正在全力推进旨在保障运河及居民用水的印第奥河人工湖项…",
    "content": "新华社巴拿马城9月7日电（记者李佳旭 许咏政）巴拿马运河管理局新任局长伊利娅·埃斯皮诺7日表示，若未来数月运河流域降雨量仍低于预期，运河每日通航量或于明年年初从32艘进一步降至约29艘。 埃斯皮诺当天正式就任巴拿马运河管理局局长，任期至2033年，系首位执掌该机构的女性。她在就职典礼上说，近年来，巴拿马运河流域经历严重水资源危机，运河通航和数百万居民用水安全均受到威胁。为此，运河管理局正在全力推进旨在保障运河及居民用水的印第奥河人工湖项目。 据介绍，该项目建成后，可为运河存蓄相当于每日增加10至15艘次船舶通航所需…"
