    "content": "新华社科威特城9月7日电（记者尹炣）萨那消息：据胡塞武装控制的萨巴通讯社7日报道，沙特当天空袭了也门北部焦夫省首府哈兹姆市一所监狱，造成7人死亡、7人受伤。 据也门胡塞武装控制的马西拉电视台当天播出的画面显示，监狱设施遭到严重损毁，救援人员正在展开搜救。报道援引监狱负责人的话称，空袭造成妇女和儿童伤亡，目前还有35名在押人员和一名探视丈夫的妇女被困在废墟下。 沙特方面尚未对此作出回应。 胡塞武装发言人叶海亚·萨雷亚7日在社交媒体平台上说，沙特在也门侦察飞行、发动空袭并向也门政府军提供武器，这些军事行动“不会没有回应…"
