    "author": "赵晨捷,李萌",
    "description": "新华社马尼拉9月7日电（记者赵晨捷 李萌）据菲律宾媒体报道，菲律宾警方7日在大马尼拉地区一家医院，向涉嫌防洪项目腐败的前众议长、菲总统马科斯的表弟马丁·罗穆亚尔德斯送达逮捕令。 菲律宾内政部长洪维克·雷穆利亚说，罗穆亚尔德斯7日下午因血压不稳定和焦虑被送医，但他目前已被剥夺自由，住院治疗不会妨碍逮捕令的执行，一旦医生判定其身体状况可以出院，他就会被移送至关押设施。 当日，一些菲众议员表示，针对罗穆亚尔德斯的调查或许只是腐败案“冰山一角”…",
    "content": "新华社马尼拉9月7日电（记者赵晨捷 李萌）据菲律宾媒体报道，菲律宾警方7日在大马尼拉地区一家医院，向涉嫌防洪项目腐败的前众议长、菲总统马科斯的表弟马丁·罗穆亚尔德斯送达逮捕令。 菲律宾内政部长洪维克·雷穆利亚说，罗穆亚尔德斯7日下午因血压不稳定和焦虑被送医，但他目前已被剥夺自由，住院治疗不会妨碍逮捕令的执行，一旦医生判定其身体状况可以出院，他就会被移送至关押设施。 当日，一些菲众议员表示，针对罗穆亚尔德斯的调查或许只是腐败案“冰山一角”。今年早些时候，罗穆亚尔德斯表示，不会让自己“成为替罪羊，却让真正应该负责的人逍…"
