    "content": "新华社耶路撒冷9月7日电（记者王卓伦 冯国芮）以色列国防军7日说，以军近日在加沙地带发动两次空袭，分别打死巴勒斯坦伊斯兰抵抗运动（哈马斯）和巴勒斯坦伊斯兰圣战组织（杰哈德）各一名武装人员。 以军发表声明说，以军6日在加沙地带沙提地区发动空袭，打死杰哈德成员苏卜希·哈德尔·阿萨姆·巴特里希。以军称，此人曾参与埋设爆炸装置、袭击在加沙地带活动的以军部队。 声明还说，以军在上周发动的空袭中，打死哈马斯“努赫巴”部队成员艾哈迈德·福阿德·哈利勒·哈拉斯。以军称，此人也曾参与埋设爆炸装置并袭击以军。 声明称，两人近期持续策划…"
