    "author": "",
    "description": "\"此前她在2023年和2024年连续两年闯入美网女单八强。\" 新华社纽约9月7日电 在刚刚结束的2026年美国网球公开赛女单第四轮比赛中，中国选手郑钦文以2:0战胜六届大满贯冠军、波兰名将斯维亚特克，晋级八强。 凭借本场胜利，郑钦文追平了自己在美网的最佳战绩。此前她在2023年和2024年连续两年闯入美网女单八强。今年美网四分之一决赛，郑钦文将对阵2号种子莱巴金娜与日本名将大坂直美之间的胜者。",
    "content": "\"此前她在2023年和2024年连续两年闯入美网女单八强。\" 新华社纽约9月7日电 在刚刚结束的2026年美国网球公开赛女单第四轮比赛中，中国选手郑钦文以2:0战胜六届大满贯冠军、波兰名将斯维亚特克，晋级八强。 凭借本场胜利，郑钦文追平了自己在美网的最佳战绩。此前她在2023年和2024年连续两年闯入美网女单八强。今年美网四分之一决赛，郑钦文将对阵2号种子莱巴金娜与日本名将大坂直美之间的胜者。 &nbsp;"
