    "content": "新华社伦敦9月7日电（记者张亚东）英国伦敦股市《金融时报》100种股票平均价格指数7日报收于10822.13点，较前一交易日下跌8.96点，跌幅为0.08%。欧洲三大股指当天涨跌不一。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：英国天然气供应商森特理克集团股价上涨2.20%，标准人寿保险股价上涨2.04%，科技企业史密斯集团股价上涨1.32%，壳牌公司股价上涨1.32%，车险企业埃德米拉尔集团股价上涨1.31%。 当天伦敦股市成分股中位于跌幅前五位的个股分别为：体育博彩公司恩坦股价下跌2.99%，消费健康企业…"
