    "content": "中新社上海9月7日电 （许婧 娄瀚锟 张亨伟）“走进人民城市：中国之治与全球互鉴”驻华使节沪苏行活动启动仪式7日在上海举行。来自白俄罗斯、西班牙、孟加拉国、塞浦路斯、纳米比亚等20个国家的30位驻华使节及外交官，将赴沪苏两地实地参访，共享城市发展先进理念和成功经验。"
