    "content": "新华社贝尔格莱德9月7日电（记者陈颖）塞尔维亚总理马楚特7日在政府特别会议后发表讲话，提出解散议会，以提前举行议会选举。 马楚特提议政府根据宪法向总统提出解散国民议会并举行议会选举的建议。马楚特说，政府一直听到部分民众要求提前举行议会选举的呼声，为了消除民众的疑虑，没有比再次将选择权交给塞尔维亚公民“更有力的回应”。 根据塞尔维亚宪法，总统可根据政府提出的建议解散国民议会，并同时确定议会选举日期。 5日，塞尔维亚进步党总委员会决定，推举现任总统武契奇为该党议会选举名单领衔人和总理候选人。武契奇接受推举，并表示将在完…"
