    "content": "新华社金边9月7日电（记者吴长伟）柬埔寨首届华文教育研讨会日前在金边举行，与会者聚焦华文教育可持续发展主题展开研讨。中国驻柬埔寨大使馆公使衔参赞赵海燕、柬华理事总会会长方侨生出席并致辞。 在5日举行的研讨会上，全柬各地华校代表和柬华社团除了围绕主题进行深入探讨外，还结合办学实践分享各自经验、建言献策。 方侨生表示，柬埔寨华文教育走过百年风雨历程。面向未来，华校要加快转型升级，深度融入柬国民教育体系，培育华校骨干管理人才，持续强化本土师资培养，广泛汇聚社会力量，改善办学条件。 赵海燕对柬埔寨华文教育取得的发展成果给予…"
