    "content": "新华社莫斯科9月7日电（记者赵冰）俄罗斯总统新闻秘书佩斯科夫7日表示，俄方不排除就乌克兰问题重启俄美乌三方会谈的可能性，但现在讨论会谈时间和地点为时尚早。 佩斯科夫在当天举行的记者会上表示，俄总统普京与美国总统特朗普的特使威特科夫和女婿库什纳的会晤是“迈向和平的一小步”。 对于威特科夫和库什纳与普京会晤时提出的建议与俄美领导人2025年在美国阿拉斯加州安克雷奇会晤时达成的共识有何不同，佩斯科夫拒绝透露。 塔斯社6日援引库什纳的话报道称，美国希望恢复三方会谈模式，这样各方能直接交流，无需美方在俄乌间传话。俄罗斯、美国…"
