    "content": "新华社昆明9月7日电 落实“健康第一”：新学期校园新气象观察 新华社记者 金秋九月，全国各地中小学迎来新学年。下课铃响，孩子们涌出教室，操场上身影跃动，笑声朗朗。这个开学季，“健康第一”的理念深度融入操场、课堂、课本与餐桌的细微日常，成为新时代青少年茁壮成长的坚实底色。 今年7月，习近平总书记对基础教育工作作出重要指示强调，要遵循教育规律，落实健康第一教育理念，提升教育教学质量，促进广大学生身心健康、成长成才。中共中央、国务院印发的《教育强国建设规划纲要（2024—2035年）》明确：中小学生每天综合体育活动时间不…"
