    "content": "新华社长春9月7日电 日前，经吉林省委批准，吉林省纪委监委对吉林省人大监察和司法委员会原副主任委员曾范涛严重违纪违法问题进行了立案审查调查。 经查，曾范涛身为党员领导干部，丧失理想信念，背弃初心使命，落实党中央决策部署不坚决，打折扣、搞变通；违反中央八项规定精神，违规收受礼品、礼金、消费卡，接受可能影响公正执行公务的宴请，搞劳民伤财的“政绩工程”；个人决定重大事项；廉洁底线失守，搞钱色交易；违规干预和插手市场经济活动；毫无纪法底线，将公权力异化为谋取私利的工具，大肆收钱敛财，利用职务便利为他人在项目承揽、企业经营等…"
