    "content": "9月6日上午11:02，G3998次复兴号列车从瑞金站首发，一路风驰电掣，于当晚22:34正点抵达延安站。从用脚板走完二万五千里，到时速300公里高铁飞驰；从一年有余的远征到11个半小时的直达，从瑞金至延安的这趟高铁，连接起两座红色地标，将信仰的力量注入时代发展的速度。 这趟“长征高铁”，途经哪些站点？票价如何？沿线有哪些值得打卡的“地标”？跟随这张长图，一起了解。 策划：石锋 统筹：令伟家 记者：赖星、王自宸、邵瑞 制作：马发展 监制：陈知春、刘雅萱、陶虹"
