    "content": "新华社加德满都9月7日电（记者张平 张东强）尼泊尔总统鲍德尔7日发表全国电视讲话，呼吁全体国民在艰难时刻团结一致，全力投入灾后重建工作。 8月26日，尼泊尔边境地区突发冰川崩塌引发严重泥石流灾害，造成重大人员伤亡。截至目前，该国泥石流受灾地区已有1355人遇难、4996人失联。此次灾害还造成道路、桥梁、水电等重要基础设施严重受损。 鲍德尔在讲话中呼吁国民保持团结，“现在是展现民族团结和凝聚力的时候，也是重建和复兴的时候”。 鲍德尔向所有遇难同胞致以深切哀悼，向遇难者家属表示诚挚慰问。他同时向不幸遇难的外国公民表示哀…"
