    "title": "特朗普要给新墨西哥州改名“新美国州”？",
    "link": "http://www.news.cn/20260907/8c4ec86b1a0d455a868dfb7bd6437cc9/c.html",
    "pub_date": "2026-09-07 21:52:15",
    "author": "惠晓霜",
    "description": "新华社北京9月7日电 美国总统特朗普6日在社交媒体上表示，他喜欢把美国的新墨西哥州改名为“新美国州”的建议。 特朗普在“真实社交”平台发帖，内容是一张新墨西哥州地图，上面用英文写着“新墨西哥”，但“墨西哥”被打了一个红叉，以“美国”取而代之，从而变成“新美国”。白宫社交媒体账号转发了这张图。 特朗普稍后又发帖，是一段人工智能生成的视频，显示他走到写着“欢迎来到新墨西哥州”的路牌前，用写着“美国”的纸张覆盖“墨西哥”，然后跳舞庆祝。 特朗…",
    "content": "新华社北京9月7日电 美国总统特朗普6日在社交媒体上表示，他喜欢把美国的新墨西哥州改名为“新美国州”的建议。 特朗普在“真实社交”平台发帖，内容是一张新墨西哥州地图，上面用英文写着“新墨西哥”，但“墨西哥”被打了一个红叉，以“美国”取而代之，从而变成“新美国”。白宫社交媒体账号转发了这张图。 特朗普稍后又发帖，是一段人工智能生成的视频，显示他走到写着“欢迎来到新墨西哥州”的路牌前，用写着“美国”的纸张覆盖“墨西哥”，然后跳舞庆祝。 特朗普在帖子中称，新墨西哥州是“选举舞弊严重的州”之一，“许多人建议把新墨西哥州改名…"
