    "content": "新华社北京9月7日电 日本冲绳县知事选举投票定于13日举行，现任知事玉城丹尼寻求连任。日本共同社7日发布的民调结果显示，玉城所获支持率与执政党自民党支持的候选人古谢玄太不相上下，选情胶着。 本届冲绳县知事选举共有6人参选，其中玉城和古谢被视为获胜可能较大的候选人。玉城2018年首次当选冲绳县知事并于2022年连任，此次寻求第三任。他获得包括立宪民主党、日本共产党在内反对美军基地县内搬迁的政党联盟“全冲绳会议”支持。古谢曾任冲绳首府那霸市副市长，获得执政的自民党和日本维新会以及国民民主党、参政党等在野党支持。 202…"
