    "description": "中新网济南9月7日电 (记者 孙婷婷)“海洋合作发展论坛已经成为深化海洋合作交流、促进海洋经济发展、推动海洋科技创新和全球海洋治理的重要平台。”山东省人民政府副省长李晓龙7日表示，2026海洋合作发展论坛将于9月16日至9月18日在青岛西海岸新区举办，主题为“从蔚蓝到未来——发展可持续海洋经济，共建美丽丰盈的海洋”。",
    "content": "中新网济南9月7日电 (记者 孙婷婷)“海洋合作发展论坛已经成为深化海洋合作交流、促进海洋经济发展、推动海洋科技创新和全球海洋治理的重要平台。”山东省人民政府副省长李晓龙7日表示，2026海洋合作发展论坛将于9月16日至9月18日在青岛西海岸新区举办，主题为“从蔚蓝到未来——发展可持续海洋经济，共建美丽丰盈的海洋”。"
