    "author": "陈霄",
    "description": "新华社德黑兰9月7日电 伊朗迈赫尔通讯社6日报道，伊朗经济部已设立“经济战争指挥部”，旨在集中研判战争造成的经济问题，并协调有关部门加快制定和落实解决方案。 伊朗经济部副部长莫尔塔扎·扎马尼安表示，该机构设在经济部内部，初期将重点处理经济部职责权限范围内的问题，包括战争给企业经营、贸易、融资等经济领域造成的影响，以加快有关问题的跟进和解决。对于超出经济部权限的问题，将通过跨部门协调处理。 他说，该机构主要任务是集中识别战争造成的问题和经…",
    "content": "新华社德黑兰9月7日电 伊朗迈赫尔通讯社6日报道，伊朗经济部已设立“经济战争指挥部”，旨在集中研判战争造成的经济问题，并协调有关部门加快制定和落实解决方案。 伊朗经济部副部长莫尔塔扎·扎马尼安表示，该机构设在经济部内部，初期将重点处理经济部职责权限范围内的问题，包括战争给企业经营、贸易、融资等经济领域造成的影响，以加快有关问题的跟进和解决。对于超出经济部权限的问题，将通过跨部门协调处理。 他说，该机构主要任务是集中识别战争造成的问题和经济运行障碍，提出可操作的解决方案，并在需要多个部门共同参与时加强协调。 美国总统…"
