    "content": "新华社安卡拉9月7日电（记者霍丹彤）土耳其副总统耶尔马兹6日公布该国2027年至2029年经济规划。根据该规划，土耳其计划在未来三年内将国防支出提高229%。 耶尔马兹表示，在国防工业领域，土耳其的建设目标是能够自主开展技术研发、生产高附加值产品。 根据该规划，提高土耳其国防工业的国产化率、推动国防技术向民用转移、加强国防工业人才培养和支持国防出口创汇是该国未来三年的重要目标。 土耳其2026年经济增长预期从此前的3.8%下调至3.3%，通胀预期从16%上调至28.4%。 据瑞典斯德哥尔摩国际和平研究所数据，土耳其…"
