    "author": "袁月明,张浩然",
    "description": "新华社北京9月7日电 题：监管部门严查直播间售卖假冒名家书画乱象 新华社“新华视点”记者袁月明、张浩然 一些短视频平台的直播间售卖所谓“名家书画”，价格极低，购买一幅“大师之作”只需几十元到几百元不等。不少中老年消费者和收藏新手以为“捡漏”，下单购买后才发现上当受骗。 “新华视点”记者调查发现，这类直播间售卖所谓“名家书画”，背后是一套成熟的诈骗链条。 针对直播间低价售卖“名家书画”乱象，多地监管部门及部分电商平台持续加强整治。 直播间…",
    "content": "新华社北京9月7日电 题：监管部门严查直播间售卖假冒名家书画乱象 新华社“新华视点”记者袁月明、张浩然 一些短视频平台的直播间售卖所谓“名家书画”，价格极低，购买一幅“大师之作”只需几十元到几百元不等。不少中老年消费者和收藏新手以为“捡漏”，下单购买后才发现上当受骗。 “新华视点”记者调查发现，这类直播间售卖所谓“名家书画”，背后是一套成熟的诈骗链条。 针对直播间低价售卖“名家书画”乱象，多地监管部门及部分电商平台持续加强整治。 直播间频现低价“名家书画” 近期，在一些短视频平台的直播间内，落款为齐白石、张大千、徐…"
