    "description": "中新网宁波9月7日电(蓝伊旎 郑佳珍 叶春梅)7日，随着左幅最后一方混凝土浇筑完成，浙江交通集团杭甬复线宁波三期项目跨G329国道连续梁桥成功合龙。作为全线5座大跨度连续梁桥中首座实现合龙的控制性工程，此次合龙标志着项目建设取得关键节点突破，为年底全线主线贯通奠定了坚实基础。",
