    "pub_date": "2026-09-07 21:17:57",
    "author": "唐诗凝,周圆",
    "description": "新华社北京9月7日电 题：权威人士解读规范车企供应商账款支付新规 新华社记者唐诗凝、周圆 工业和信息化部、市场监管总局7日对外发布《关于推动汽车企业规范供应商账款支付 优化账期管理的通知》。相关要求有哪些考虑？如何更好保障政策落地？工业和信息化部相关负责人回答了记者提问。 汽车企业对供应商账款支付期限过长是非理性竞争的典型表现，必须采取有力措施推动解决。记者了解到，2025年6月，17家重点汽车企业公开作出“支付账期不超过60天”的承诺…",
    "content": "新华社北京9月7日电 题：权威人士解读规范车企供应商账款支付新规 新华社记者唐诗凝、周圆 工业和信息化部、市场监管总局7日对外发布《关于推动汽车企业规范供应商账款支付 优化账期管理的通知》。相关要求有哪些考虑？如何更好保障政策落地？工业和信息化部相关负责人回答了记者提问。 汽车企业对供应商账款支付期限过长是非理性竞争的典型表现，必须采取有力措施推动解决。记者了解到，2025年6月，17家重点汽车企业公开作出“支付账期不超过60天”的承诺。中国汽车工业协会发布《汽车整车企业供应商账款支付规范倡议》，积极推进承诺落实。…"
