    "content": "新华社东京9月7日电（记者李子越 陈泽安）日本、美国和韩国7日在东海举行“自由之刃”联合军演，将持续至11日。相关动向引发日本民间团体抗议。 日本时事社援引日本防卫省统合幕僚监部消息称，此次联合军演中，除了日本派出宙斯盾舰“爱宕”号、P－1巡逻机以外，三国还将投入舰艇、战斗机等装备。联合军演将围绕海空作战以及太空、网络等多个领域展开，并推动扩大一体化防空反导合作。 日本广播协会称，这是三国第四次举行“自由之刃”联合军演。美韩上月的联合军演规模有所缩减，三国希望通过此次军演再次确认彼此间的合作关系。 此次军演在日本民…"
