    "content": "我每次旅行都喜欢在十字路口拍照。这次来到深圳，我也特别注意到这里道路规划非常清晰，道路宽阔，整个城市建设都是经过规划的，科技与城市建设高度融合。 我特别喜欢这次论坛的一点，就是中国试图推动大国和小国之间的共同利益。这与柬埔寨当前所倡导的一些理念也比较契合。 南方周末记者 王航 毛淑杰 发自：广东 深圳 责任编辑：姚忆江 “柬埔寨什么时候才能有这样的交通？”坐在时速160公里的广州地铁18号线上，柬埔寨皇家科学院公共关系部主任森桑 （Seun Sam） 忍不住向同事感叹。 2026年9月5日，亚太媒体高端论坛在深圳前…"
