    "content": "张绪武同志遗像 新华社发 新华社北京9月7日电 中华全国工商业联合会的优秀领导人，中国共产党的亲密朋友，中华全国工商业联合会第七届、八届常务副主席张绪武同志（正部长级），因病于2026年9月3日在北京逝世，享年98岁。 张绪武同志逝世后，中央有关领导同志以不同方式表示哀悼并向其亲属表示慰问。 张绪武，1928年3月生，江苏南通人，无党派人士。1949年2月参加革命工作。1950年至1979年，历任黑龙江省佳木斯市纺织厂技术员、科长、工程师。1979年至1981年任江苏省南通市纺织局副局长。1981年至1983年任江…"
