    "content": "新华社昆明9月7日电 题：多方呼吁全球协同共治 推动“昆蒙框架”落地见效 新华社记者高敬、严勇 记者7日从《昆明—蒙特利尔全球生物多样性框架》实施进展全球审议昆明对话会上获悉，在“昆蒙框架”引领下，全球行动总体呈现积极推进态势，但与“昆蒙框架”雄心之间的落差依然较大，与会人士呼吁以务实行动推动“昆蒙框架”全面平衡有效执行。 据悉，“昆蒙框架”是《生物多样性公约》第十五次缔约方大会（COP15）的重要成果，是各缔约方就到2030年遏制并扭转生物多样性丧失而达成的路线图。框架确立了到2050年的4个长期目标以及到203…"
