    "content": "新华社香港9月7日电（谢妞）由香港科技园公司举办的“共创共投产业加速峰会”7日在港举行。会上公布“共同企业加速基金”首批投资项目，推动创科企业、投资者及产业合作伙伴形成三方协作生态圈，加快技术验证、商业落地及国际拓展。 一连6日的峰会联动香港、东莞及杭州，逾400名创科企业家、投资者参与，对接约100个产业应用场景。峰会前两天在香港科学园进行，议题涵盖全球深科技投资趋势、科技企业出海策略、场景介绍等，其后到东莞及杭州与当地创科生态展开深度产业对接与交流，包括参观创科培育中心、中试基地，并与当地企业及投资者举行圆桌会…"
