    "content": "当视频通话里的“熟人”开口借钱，当知名人物的头像被一键复刻……人工智能技术在赋能发展的同时，也给社会安全防线带来挑战。 如何让人工智能这匹千里马既跑得快又跑得稳？最高人民法院9月7日发布关于依法审理涉人工智能纠纷案件的意见，加强数字时代民事权益司法保障，促推人工智能健康有序发展。 意见共5个部分24条，精准聚焦社会各界普遍关注的“AI换脸拟声”、“AI幻觉”侵权、“网络开盒”、“大数据杀熟”、自动驾驶、AI模型训练等问题，针对性明确涉人工智能纠纷案件实体裁判和诉讼程序规则。 几张照片、几十秒录音，就足以制造出以假乱…"
