    "content": "新华网北京9月7日电（记者李春宇）7日，国家体育总局与清华大学在北京签署战略合作协议。 该协议约定，双方将以“战略协同、优势互补、平等合作、共赢发展”为原则，以服务体育和教育事业高质量发展为目标，聚焦高水平竞技运动员培养、优秀运动员文化教育、体育专业人才培养、重大问题研究、科技创新和国际交流等重点领域开展深度合作。 据悉，体育总局与清华大学开展战略合作是进一步深化体教融合、推进体育强国建设和教育强国建设的重要举措。双方将结合体育事业与学校发展的新形势、新要求，以创建体教融合新模式、服务清华大学发展和竞技体育训练备战…"
