    "description": "鲁派内画是国家级非物质文化遗产代表性项目，是国内四大内画流派之一。创作者手持弯钩画笔，探入口小如豆的鼻烟壶内部反向运笔，于方寸之间绘就万千气象。作为第四代鲁派内画传承人，中国内画艺术大师张路华承续家学渊源，在坚守传统的基础上不断创新，为古老非遗注入时代活力。 张路华出身内画世家，父亲张广庆是鲁派内画第三代传承人。1992年，张广庆在山东淄川成立张广庆内画艺术研究院，张路华自小喜爱绘画，研究院创办后，他正式踏上内画学习之路。为打好扎实的艺…",
    "content": "鲁派内画是国家级非物质文化遗产代表性项目，是国内四大内画流派之一。创作者手持弯钩画笔，探入口小如豆的鼻烟壶内部反向运笔，于方寸之间绘就万千气象。作为第四代鲁派内画传承人，中国内画艺术大师张路华承续家学渊源，在坚守传统的基础上不断创新，为古老非遗注入时代活力。 张路华出身内画世家，父亲张广庆是鲁派内画第三代传承人。1992年，张广庆在山东淄川成立张广庆内画艺术研究院，张路华自小喜爱绘画，研究院创办后，他正式踏上内画学习之路。为打好扎实的艺术根底，张路华先后在南京艺术学院、中央美院学习。他打破传统内画重精细、轻笔墨的局…"
