    "content": "新华社日内瓦9月7日电（记者王露）世界气象组织7日发布最新报告，通过追踪空气质量与气候之间的复杂关系，揭示了气溶胶（包括颗粒物、黑碳、微塑料等）和近地面臭氧对人体健康的负面影响，并呼吁加强监测。 该组织于9月7日“国际清洁空气蓝天日”发布2025年度《空气质量与气候公报》指出，PM2.5颗粒物由直径小于2.5微米的微小颗粒和液滴组成，能深入肺部和血液，对健康构成威胁。PM2.5排放源多种多样，包括工业活动、农业、居民供暖和交通运输，以及野火和沙尘暴等。 2025年，加拿大北部、俄罗斯部分地区、非洲中西部以及西班牙西…"
